<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetAsset\Application\Usecase\List;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\SnippetAsset\Application\Service\Visibility\SnippetAssetVisibilityService;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetReadGateway;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetFilter;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetCursor;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetAttributesSlide;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class SnippetAssetListUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly SnippetAssetVisibilityService $visibility,
        private readonly SnippetAssetReadGateway $reader
    ) {
    }

    public function allowList(): Allow
    {
        $this->logDebug("Check allow of list usecase for Snippet asset");
        $span = $this->startSpan("Check allow of list usecase for Snippet asset");
        try {
            $result = $this->dispatcher->dispatch(new SnippetAssetListAllowDecision(Allow::allowed('list', 'Allowed to list by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function count(SnippetAssetFilter $filter): int
    {
        $this->logDebug("Run list usecase for Snippet asset");
        $span = $this->startSpan("Run list usecase for Snippet asset");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list Snippet asset');
            }
            return $this->visibility->countVisibles($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function list(SnippetAssetFilter $filter, ?SnippetAssetCursor $cursor = null): SnippetAssetAttributesSlide
    {
        $this->logDebug("Run list usecase for Snippet asset");
        $span = $this->startSpan("Run list usecase for Snippet asset");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list');
            }
            $slide = $this->visibility->listVisibles($filter, $cursor);
            return new SnippetAssetAttributesSlide($slide->nextCursor(), array_map(fn ($item) => $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($item)), $slide->values()));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
